function reply(array $body, int $status = 200): never {
    http_response_code($status); echo json_encode($body, JSON_UNESCAPED_SLASHES); exit;
}
function input(): array { return json_decode(file_get_contents('php://input'), true) ?: []; }
function createEmailVerificationCode(PDO $db, int $userId, string $email): string|false {
    $db->beginTransaction();
    try {
        $q=$db->prepare('SELECT email,email_verified_at FROM users WHERE user_id=? FOR UPDATE');$q->execute([$userId]);$user=$q->fetch();
        if(!$user||$user['email_verified_at']){$db->rollBack();return false;}
        $code=str_pad((string)random_int(0,999999),6,'0',STR_PAD_LEFT);
        $db->prepare('UPDATE email_verification_tokens SET used_at=UTC_TIMESTAMP() WHERE user_id=? AND used_at IS NULL')->execute([$userId]);
        $db->prepare('INSERT INTO email_verification_tokens(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 15 MINUTE))')->execute([$userId,hash('sha256',$code)]);
        $db->commit();
        \StarGuess\Config\EmailService::sendCode($email,'Verify your StarGuess email',$code);
        return $code;
    }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
}
function audit(PDO $db, array $admin, string $action, string $kind, string $id, array $before, array $after, string $reason): void {
    $q = $db->prepare('INSERT INTO admin_activity_logs (admin_id,action,target_type,target_id,before_value_json,after_value_json,reason,ip_address,user_agent) VALUES (?,?,?,?,?,?,?,?,?)');
    $q->execute([$admin['admin_id'],$action,$kind,$id,json_encode($before),json_encode($after),$reason,$_SERVER['REMOTE_ADDR'] ?? 'unknown',substr($_SERVER['HTTP_USER_AGENT'] ?? '',0,255)]);
}
function admin(PDO $db): array {
    $header = $_SERVER['HTTP_AUTHORIZATION'] ?? $_SERVER['REDIRECT_HTTP_AUTHORIZATION'] ?? $_SERVER['Authorization'] ?? '';
    if (!preg_match('/^Bearer ([A-Za-z0-9_-]{40,})$/', $header, $m)) reply(['success'=>false,'error_code'=>'UNAUTHORIZED','message'=>'Sign in required.'],401);
    $q = $db->prepare('SELECT a.admin_id,a.username,a.email,a.full_name,a.role_id,r.role_name,r.permissions_json FROM admin_sessions s JOIN admins a ON a.admin_id=s.admin_id JOIN admin_roles r ON r.role_id=a.role_id WHERE s.token_hash=? AND s.expires_at>UTC_TIMESTAMP() AND a.is_active=1');
    $q->execute([hash('sha256',$m[1])]); $row=$q->fetch();
    if (!$row) reply(['success'=>false,'error_code'=>'INVALID_SESSION','message'=>'Session expired. Sign in again.'],401);
    $row['permissions']=json_decode($row['permissions_json'],true) ?: [];
    return $row;
}
function requirePerm(array $a,string $perm): void {
    $p=$a['permissions']; $ns=explode(':',$perm)[0];
    if (!in_array('*',$p,true) && !in_array($perm,$p,true) && !in_array($ns.':*',$p,true)) reply(['success'=>false,'error_code'=>'FORBIDDEN','message'=>'Permission denied.'],403);
}
function user(PDO $db): array {
    $header=$_SERVER['HTTP_AUTHORIZATION']??$_SERVER['REDIRECT_HTTP_AUTHORIZATION']??$_SERVER['Authorization']??'';
    if(!preg_match('/^Bearer ([a-f0-9]{64})$/',$header,$m)) reply(['success'=>false,'error_code'=>'UNAUTHORIZED','message'=>'Sign in required.'],401);
    $q=$db->prepare('SELECT u.user_id,u.username,u.email,u.status,u.games_played,u.games_won,w.balance FROM user_sessions s JOIN users u ON u.user_id=s.user_id JOIN wallets w ON w.user_id=u.user_id WHERE s.session_id=? AND s.expires_at>UTC_TIMESTAMP() AND u.status=\'ACTIVE\'');$q->execute([$m[1]]);$u=$q->fetch();
    if(!$u) reply(['success'=>false,'error_code'=>'INVALID_SESSION','message'=>'Session expired. Sign in again.'],401);
    $u['user_id'] = (int)$u['user_id']; $u['games_played'] = (int)$u['games_played']; $u['games_won'] = (int)$u['games_won']; $u['balance'] = (int)$u['balance']; return $u;
}
function issueUser(PDO $db,array $u): never {
    $token=bin2hex(random_bytes(32));$db->prepare('INSERT INTO user_sessions(session_id,user_id,ip_address,user_agent,expires_at) VALUES(?,?,?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 8 HOUR))')->execute([$token,$u['user_id'],$_SERVER['REMOTE_ADDR']??'unknown',substr($_SERVER['HTTP_USER_AGENT']??'',0,255)]);
    reply(['success'=>true,'data'=>['token'=>$token,'user'=>['user_id'=>(int)$u['user_id'],'username'=>$u['username'],'email'=>$u['email']]]]);
}
function walletEntry(PDO $db, int $uid, int $amount, string $type, string $ref, string $notes): void {
    $q=$db->prepare('SELECT wallet_id,balance FROM wallets WHERE user_id=? FOR UPDATE');$q->execute([$uid]);$w=$q->fetch();if(!$w)throw new RuntimeException('Wallet not found.');$before=(int)$w['balance'];$after=$before+$amount;if($after<0)throw new RuntimeException('Not enough Stars for this match.');
    if($type==='GAME_WIN')$db->prepare('UPDATE wallets SET balance=?,won_balance=won_balance+?,version=version+1 WHERE wallet_id=?')->execute([$after,$amount,$w['wallet_id']]);elseif($type==='BONUS')$db->prepare('UPDATE wallets SET balance=?,bonus_balance=bonus_balance+?,version=version+1 WHERE wallet_id=?')->execute([$after,$amount,$w['wallet_id']]);elseif($type==='TRANSFER_RECEIVED')$db->prepare('UPDATE wallets SET balance=?,transferred_balance=transferred_balance+?,version=version+1 WHERE wallet_id=?')->execute([$after,$amount,$w['wallet_id']]);else$db->prepare('UPDATE wallets SET balance=?,version=version+1 WHERE wallet_id=?')->execute([$after,$w['wallet_id']]);
    if($type==='GAME_ENTRY')$db->prepare('UPDATE users SET total_stars_spent=total_stars_spent+? WHERE user_id=?')->execute([abs($amount),$uid]);
    $db->prepare('INSERT INTO star_transactions(transaction_id,user_id,wallet_id,type,amount,balance_before,balance_after,reference_type,reference_id,notes,status) VALUES(?,?,?,?,?,?,?,?,?,?,\'COMPLETED\')')->execute(['TX_'.bin2hex(random_bytes(15)),$uid,$w['wallet_id'],$type,$amount,$before,$after,'GAME',$ref,$notes]);
}
function platformCommission(PDO $db, string $gameId, int $amount): void {
    $q=$db->query('SELECT balance FROM platform_wallets WHERE wallet_id=1 FOR UPDATE');$before=(int)$q->fetchColumn();$after=$before+$amount;$db->prepare('UPDATE platform_wallets SET balance=? WHERE wallet_id=1')->execute([$after]);$db->prepare('INSERT INTO platform_transactions(transaction_id,game_id,type,amount,balance_before,balance_after) VALUES(?,?,\'COMMISSION\',?,?,?)')->execute(['TX_COM_'.bin2hex(random_bytes(12)),$gameId,$amount,$before,$after]);
}
